601 :           .setClosureEntryPoints(flags.closure_entry_point)
602 :           .setOutputManifest(ImmutableList.of(flags.output_manifest))
603 :           .setAcceptConstKeyword(flags.accept_const_keyword)
604 :           .setLanguageIn(flags.language_in);
605 :     }
